def f(g, marker=6):
    g=[row[:] for row in g]; bg=g[0][0]
    cells=[(i,j,g[i][j]) for i in range(len(g)) for j in range(len(g[0])) if g[i][j] not in (bg,marker)]
    rs=[c[0] for c in cells]; cs=[c[1] for c in cells]
    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
    P=[[g[i][j] for j in range(c0,c1+1)] for i in range(r0,r1+1)]
    h,w=len(P),len(P[0]); ci,cj=h//2,w//2
    out=[row[:] for row in g]
    for i in range(len(g)):
        for j in range(len(g[0])):
            if g[i][j]==marker:
                for a in range(h):
                    for b in range(w):
                        r,c=i-ci+a,j-cj+b
                        if 0<=r<len(g) and 0<=c<len(g[0]) and P[a][b]!=bg:
                            out[r][c]=P[a][b]
    return out
